import type { BankQuestion } from "@/lib/bank";

/** Kinematics (Physics (JEE/NEET)): 129 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-kinematics-1","question":"A body starts from rest and moves with a uniform acceleration of 2 m/s². The distance covered in the first 5 s is:","options":["10 m","25 m","50 m","100 m"],"answer":1,"explanation":"s = ut + ½at² = 0 + ½ × 2 × 5² = 25 m. Using v = at = 10 m/s and then s = vt = 50 m (option 3) wrongly treats the final speed as constant.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-2","question":"The slope of a velocity–time graph at any instant gives the:","options":["displacement","distance travelled","speed","acceleration"],"answer":3,"explanation":"dv/dt is acceleration, so the slope of the v–t graph is the instantaneous acceleration; the area under the v–t graph gives displacement.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-kinematics-3","question":"For a given speed of projection on level ground (air resistance neglected), the horizontal range is maximum when the angle of projection is:","options":["30°","45°","60°","90°"],"answer":1,"explanation":"R = u² sin2θ/g is maximum when sin2θ = 1, i.e. θ = 45°. Complementary angles such as 30° and 60° give equal but smaller ranges.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-kinematics-4","question":"A ball is thrown vertically upward with a speed of 20 m/s (g = 10 m/s²). The maximum height reached is:","options":["20 m","10 m","40 m","80 m"],"answer":0,"explanation":"At the top v = 0, so H = u²/2g = 400/20 = 20 m. It takes 2 s to rise and 4 s in total to return to the hand.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-kinematics-5","question":"A car covers the first half of a distance at 40 km/h and the second half at 60 km/h. Its average speed for the whole journey is:","options":["50 km/h","48 km/h","45 km/h","52 km/h"],"answer":1,"explanation":"Equal distances: average speed = 2v₁v₂/(v₁ + v₂) = 2 × 40 × 60/100 = 48 km/h. The arithmetic mean 50 km/h would be correct only for equal times, not equal distances.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-6","question":"A projectile is fired at 20 m/s at an angle of 45° to the horizontal (g = 10 m/s²). Its maximum height is:","options":["20 m","40 m","10 m","5 m"],"answer":2,"explanation":"H = u² sin²θ/2g = 400 × (1/2)/20 = 10 m. The range here is 40 m (option 2) — at 45° the range is exactly four times the maximum height.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-kinematics-7","question":"Two trains of lengths 100 m and 150 m move towards each other on parallel tracks at 15 m/s and 10 m/s. The time they take to cross each other completely is:","options":["5 s","8 s","12 s","10 s"],"answer":3,"explanation":"Relative speed = 15 + 10 = 25 m/s and the relative distance to be covered is the sum of lengths, 250 m, so t = 250/25 = 10 s.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-8","question":"A particle moves along a semicircular path of radius R from one end of the diameter to the other. The ratio of distance travelled to the magnitude of displacement is:","options":["π","π/2","2","2/π"],"answer":1,"explanation":"Distance = half circumference = πR; displacement = diameter = 2R; ratio = πR/2R = π/2.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-kinematics-9","question":"The velocity–time graph of a particle is a straight line through the origin with positive slope. Its position–time graph is:","options":["a straight line through the origin","a straight line parallel to the time axis","a hyperbola","a parabola"],"answer":3,"explanation":"v ∝ t means constant acceleration starting from rest, so x = ½at² — a parabola. A straight x–t line would need constant velocity.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-kinematics-10","question":"A stone dropped from the top of a tower covers 45 m in the last second of its fall (g = 10 m/s²). The height of the tower is:","options":["125 m","100 m","80 m","180 m"],"answer":0,"explanation":"Distance in the nth second = g(2n − 1)/2 = 5(2n − 1) = 45 gives n = 5 s. Height = ½ × 10 × 5² = 125 m.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-11","question":"A ball is thrown vertically upward at 20 m/s from the top of a 60 m tower (g = 10 m/s²). It reaches the ground after:","options":["4 s","2 s","6 s","8 s"],"answer":2,"explanation":"Taking up positive: −60 = 20t − 5t², i.e. t² − 4t − 12 = 0, (t − 6)(t + 2) = 0, so t = 6 s. (4 s is only the time to come back to the launch level.)","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-12","question":"A projectile is launched at 20 m/s at 60° to the horizontal (g = 10 m/s²). After what time is its velocity perpendicular to its initial velocity?","options":["2 s","2√3 s","4/√3 s","√3 s"],"answer":2,"explanation":"Velocity at time t is (u cosθ, u sinθ − gt); its dot product with the initial velocity is u² − u g t sinθ = 0, so t = u/(g sinθ) = 20/(10 × √3/2) = 4/√3 ≈ 2.31 s, which is less than the flight time 2√3 s, so it does occur.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-13","question":"A river 400 m wide flows at 3 m/s. A boat can move at 5 m/s relative to still water. The time taken to cross by the shortest path (reaching the point directly opposite) is:","options":["80 s","50 s","125 s","100 s"],"answer":3,"explanation":"To go straight across the boat heads upstream so that its velocity across the river is √(5² − 3²) = 4 m/s; t = 400/4 = 100 s. Heading straight across gives the shortest time, 80 s, but with 240 m of drift.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-14","question":"A man walking at 3 m/s finds the rain falling vertically. When he doubles his speed, the rain appears to hit him at 45° to the vertical. The actual speed of the rain is:","options":["3 m/s","6 m/s","3√2 m/s","3√3 m/s"],"answer":2,"explanation":"Rain appearing vertical at 3 m/s means its horizontal component is 3 m/s. At 6 m/s the relative horizontal component is 3 m/s and the angle is 45°, so the vertical component is also 3 m/s. Speed = √(3² + 3²) = 3√2 m/s.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-15","question":"A particle starts from rest. Its acceleration is +2 m/s² for 0–2 s and −2 m/s² for 2–4 s. The displacement at t = 4 s is:","options":["0 m","16 m","4 m","8 m"],"answer":3,"explanation":"Velocity rises to 4 m/s at t = 2 s and falls back to 0 at t = 4 s, so the v–t graph is a triangle of base 4 s and height 4 m/s: displacement = ½ × 4 × 4 = 8 m. The velocity is zero at 4 s but the displacement is not.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-kinematics-16","question":"A particle starts from rest at the origin with acceleration a = 6t m/s². Its displacement in the first 2 s is:","options":["12 m","8 m","24 m","16 m"],"answer":1,"explanation":"v = ∫6t dt = 3t²; x = ∫3t² dt = t³; at t = 2 s, x = 8 m. Using s = ½at² with a evaluated at t = 2 (a = 12) gives the wrong 24 m since the acceleration is not constant.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-17","question":"The velocity of a particle moving along the x-axis depends on position as v = 2√x (SI units). Its acceleration is:","options":["zero","proportional to √x","proportional to x","2 m/s², constant"],"answer":3,"explanation":"a = v dv/dx = 2√x × (2 × 1/(2√x)) = 2 m/s², independent of x. The motion is uniformly accelerated even though v is written as a function of x.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-18","question":"A stone is dropped from a height of 100 m and at the same instant another is thrown vertically upward from the ground at 25 m/s (g = 10 m/s²). They meet at a height above the ground of:","options":["20 m","50 m","40 m","80 m"],"answer":0,"explanation":"Relative velocity is 25 m/s (g cancels), so they meet at t = 100/25 = 4 s. The upward stone is then at 25 × 4 − 5 × 16 = 20 m above the ground.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-19","question":"A ball is thrown horizontally at 30 m/s from the top of an 80 m tower (g = 10 m/s²). The angle its velocity makes with the horizontal when it hits the ground is:","options":["tan⁻¹(3/4)","45°","tan⁻¹(4/3)","60°"],"answer":2,"explanation":"Fall time t = √(2 × 80/10) = 4 s, so vᵧ = 40 m/s while vₓ stays 30 m/s. tanφ = 40/30 = 4/3, giving φ = tan⁻¹(4/3) ≈ 53°; the impact speed is 50 m/s.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-20","question":"For a projectile on level ground (no air resistance), how many of the following statements are correct?\n(A) At the highest point the velocity and the acceleration are perpendicular.\n(B) Two projectiles fired with the same speed at complementary angles have equal ranges.\n(C) Two projectiles fired with the same speed at complementary angles have equal times of flight.\n(D) The range is maximum when the horizontal and vertical components of the initial velocity are equal.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(A), (B) and (D) are correct: at the top v is horizontal and g vertical; sin2θ is the same for θ and 90° − θ; equal components mean θ = 45°. (C) is false — time of flight 2u sinθ/g differs for 30° and 60°.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-21","question":"A projectile is fired at 20 m/s at 60° to the horizontal (g = 10 m/s²). The radius of curvature of its path at the highest point is:","options":["20 m","40 m","5 m","10 m"],"answer":3,"explanation":"At the top the speed is u cos60° = 10 m/s and the whole of g acts as centripetal acceleration, so r = v²/g = 100/10 = 10 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-22","question":"A car starts from rest and accelerates at 2 m/s² for 10 s, then moves at constant velocity for 20 s, and finally decelerates uniformly at 2 m/s² to rest. Its average speed for the whole journey is:","options":["20 m/s","15 m/s","12 m/s","16 m/s"],"answer":1,"explanation":"Phase 1: v = 20 m/s, s = 100 m. Phase 2: s = 20 × 20 = 400 m. Phase 3: t = 10 s, s = 100 m. Total 600 m in 40 s, so average speed = 15 m/s.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-23","question":"Water drops fall at regular intervals from a tap 80 m above the ground. The fifth drop is just leaving the tap when the first drop hits the ground (g = 10 m/s²). The height of the third drop above the ground at that instant is:","options":["60 m","45 m","20 m","75 m"],"answer":0,"explanation":"The first drop takes √(2 × 80/10) = 4 s, so the interval between drops is 1 s. The third drop has fallen for 2 s: 5 × 2² = 20 m, so it is 80 − 20 = 60 m above the ground.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-kinematics-24","question":"Particle A is at the origin moving at 4 m/s along +x. Particle B is 10 m due north of A and moves at 3 m/s due south. The minimum separation between them is:","options":["6 m","8 m","10 m","5 m"],"answer":1,"explanation":"Separation² = (4t)² + (10 − 3t)² = 25t² − 60t + 100, minimum at t = 1.2 s: d² = 36 − 72 + 100 = 64, so dₘᵢₙ = 8 m. Equivalently, the component of the initial separation perpendicular to the relative velocity (5 m/s) is 10 × 4/5 = 8 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-25","question":"Which of the following statements about a position–time (x–t) graph is NOT correct?","options":["Its slope at a point gives the instantaneous velocity","A line parallel to the time axis represents a body at rest","A segment parallel to the position axis represents a very fast motion","A parabola opening upward indicates uniformly accelerated motion"],"answer":2,"explanation":"A segment parallel to the x-axis would mean the body has many positions at the same instant (infinite velocity), which is impossible; the other three statements are standard properties of the x–t graph.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-kinematics-26","question":"A lift is accelerating upward at 2 m/s². A ball is released from rest (relative to the lift) at a height of 1.5 m above the lift floor (g = 10 m/s²). The time it takes to hit the floor is:","options":["0.5 s","√0.3 s","0.6 s","0.25 s"],"answer":0,"explanation":"In the lift frame the ball's effective acceleration is g + a = 12 m/s² downward, so 1.5 = ½ × 12 × t², t² = 0.25, t = 0.5 s. Using g alone gives √0.3 ≈ 0.55 s, which ignores the lift's acceleration.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-27","question":"A projectile passes through the same height h at times t = 1 s and t = 3 s after launch (g = 10 m/s²). Its maximum height is:","options":["25 m","15 m","40 m","20 m"],"answer":3,"explanation":"The two times are roots of h = uᵧt − 5t², so t₁ + t₂ = uᵧ/5, giving uᵧ = 20 m/s and h = 5t₁t₂ = 15 m. Maximum height = uᵧ²/2g = 400/20 = 20 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-28","question":"A particle is projected at 10√3 m/s at 30° above an inclined plane that itself makes 30° with the horizontal (g = 10 m/s²). The range along the incline is:","options":["30 m","10 m","15 m","20 m"],"answer":3,"explanation":"Along the incline: time of flight T = 2u sinα/(g cosβ) = 2 × 10√3 × 0.5/(10 × √3/2) = 2 s. Range = u cosα × T − ½ g sinβ × T² = 10√3 × (√3/2) × 2 − 5 × 0.5 × 4 = 30 − 10 = 20 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-29","question":"Assertion (A): The average velocity of a particle over an interval can be zero while its average speed is non-zero.\nReason (R): Displacement over a round trip is zero but the distance travelled is not.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Average velocity = displacement/time and average speed = distance/time; for a round trip the displacement is zero but the distance is positive, which is exactly why A holds.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-kinematics-30","question":"A body starts from rest with uniform acceleration. The ratio of the distance covered in the 4th second to the total distance covered in the first 4 seconds is:","options":["1/4","7/16","7/8","1/16"],"answer":1,"explanation":"Distance in nth second = a(2n − 1)/2, so for n = 4 it is 7a/2; distance in n seconds = ½an² = 8a. Ratio = (7a/2)/8a = 7/16.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-31","question":"A wheel makes 120 revolutions per minute. Its angular speed is:","options":["120π rad/s","240π rad/s","4π rad/s","2π rad/s"],"answer":2,"explanation":"120 rev/min = 2 rev/s, and each revolution is 2π rad, so ω = 4π rad/s. 240π rad/s forgets to convert minutes to seconds.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-32","question":"The position of a particle moving along the x-axis is x = t³ − 6t² + 9t (SI units). Its velocity is zero at:","options":["t = 0 and t = 3 s","t = 3 s only","t = 2 s only","t = 1 s and t = 3 s"],"answer":3,"explanation":"v = dx/dt = 3t² − 12t + 9 = 3(t − 1)(t − 3), which vanishes at t = 1 s and t = 3 s. t = 2 s is where the acceleration (6t − 12) is zero.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-33","question":"Two projectiles are thrown with the same speed at 30° and 60° to the horizontal. The ratio of their maximum heights is:","options":["3 : 1","1 : √3","1 : 3","1 : 1"],"answer":2,"explanation":"H ∝ sin²θ: sin²30°/sin²60° = (1/4)/(3/4) = 1/3. Their ranges are equal, since the angles are complementary, but the heights are not.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-kinematics-34","question":"A stone dropped from rest falls freely (g = 10 m/s²). The distance it covers during the 3rd second of its fall is:","options":["30 m","45 m","20 m","25 m"],"answer":3,"explanation":"sₙ = u + g(2n − 1)/2 = 0 + 10 × 5/2 = 25 m. 45 m is the total distance in the first 3 s.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-35","question":"The velocity of a particle is v = 4 − 2t (SI units). The distance it travels in the first 3 seconds is:","options":["6 m","4 m","3 m","5 m"],"answer":3,"explanation":"The particle stops at t = 2 s and turns back. Distance from 0 to 2 s = 4 m (area of the triangle) and from 2 to 3 s = 1 m, total 5 m. The displacement is 4 − 1 = 3 m, the tempting wrong answer.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-36","question":"A projectile on level ground has its horizontal range equal to its maximum height. Its angle of projection is:","options":["tan⁻¹ (1/4)","tan⁻¹ 2","45°","tan⁻¹ 4"],"answer":3,"explanation":"u² sin2θ/g = u² sin²θ/2g → 2 sinθ cosθ = sin²θ/2 → tanθ = 4. (In general R = 4H cotθ, so R = 4H at 45°.)","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-37","question":"Car A moving at 20 m/s is 50 m behind car B moving at 10 m/s in the same direction on a straight road. The minimum uniform retardation A must apply at once to avoid hitting B is:","options":["0.5 m/s²","1 m/s²","2 m/s²","4 m/s²"],"answer":1,"explanation":"Relative to B, A approaches at 10 m/s and must lose this relative speed within 50 m: a = v²/2s = 100/100 = 1 m/s². Using A's full 20 m/s gives 4 m/s², which ignores that B is also moving.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-38","question":"A particle moves on a circle of radius 2 m. At an instant its speed is 4 m/s and its speed is increasing at 6 m/s². The magnitude of its acceleration at that instant is:","options":["14 m/s²","10 m/s²","6 m/s²","8 m/s²"],"answer":1,"explanation":"Centripetal a = v²/r = 16/2 = 8 m/s² and tangential a = 6 m/s², perpendicular to each other: |a| = √(64 + 36) = 10 m/s².","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-kinematics-39","question":"A ball is thrown from the top of a 15 m high building at 20 m/s, 30° above the horizontal (g = 10 m/s²). The horizontal distance from the foot of the building at which it lands is:","options":["20√3 m","10√3 m","40√3 m","30√3 m"],"answer":3,"explanation":"Vertical: −15 = 10t − 5t² → t² − 2t − 3 = 0 → t = 3 s. Horizontal speed = 20 cos30° = 10√3 m/s, so x = 30√3 m (≈ 52 m). The level-ground range 20√3 m ignores the extra fall.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-40","question":"A river 120 m wide flows at 4 m/s. A boat can move at 2 m/s relative to the water. If it is steered to reach the opposite bank with the least possible drift downstream, that drift is:","options":["120 m","60√3 m","120√3 m","240 m"],"answer":2,"explanation":"Since the boat is slower than the river, it cannot go straight across. Least drift needs heading so that the resultant makes angle φ with the bank where sinφ = 2/4, i.e. φ = 30°. Drift = 120 cot30° = 120√3 m (≈ 208 m). Heading straight across would give 240 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-41","question":"A particle moving in a straight line with initial speed v₀ is decelerated by a retardation proportional to the square of its speed (a = −kv²). Its speed after travelling a distance x is:","options":["v₀ − kx","v₀e^(−kx)","v₀e^(−kx²)","v₀/(1 + kv₀x)"],"answer":1,"explanation":"Write a = v dv/dx = −kv², so dv/v = −k dx and v = v₀e^(−kx). v₀/(1 + kv₀t) is the speed as a function of time, not distance.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-42","question":"How many of the following statements about circular motion are correct?\n(A) In uniform circular motion the acceleration is constant.\n(B) In non-uniform circular motion the acceleration is not directed towards the centre.\n(C) In uniform circular motion about a fixed axis the angular velocity vector is constant.\n(D) A body moving at constant speed has constant velocity.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"B is correct (a tangential component exists) and C is correct. A is wrong: the magnitude is constant but the direction keeps changing. D is wrong: the direction of velocity can change at constant speed. So only two are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-kinematics-43","question":"Two balls are projected from the same point on level ground with the same speed, at 15° and 75° to the horizontal. The ratio of their times of flight is:","options":["1","1/√3","2 − √3","2 + √3"],"answer":2,"explanation":"Both have the same range (complementary angles), but T ∝ sinθ: sin15°/sin75° = tan15° = 2 − √3 ≈ 0.27.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-44","question":"A particle starts from rest and its acceleration is a = (4 − 2t) m/s². Its maximum speed, and its displacement from the start when it next comes to rest, are:","options":["2 m/s and 8 m","4 m/s and 32/3 m","4 m/s and 16/3 m","8 m/s and 32/3 m"],"answer":1,"explanation":"v = 4t − t², maximum at t = 2 s (a = 0): 8 − 4 = 4 m/s. v = 0 again at t = 4 s; x = 2t² − t³/3 = 32 − 64/3 = 32/3 m. 16/3 m is the displacement at the time of maximum speed.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-45","question":"Assertion (A): For a given speed of projection, the horizontal range is maximum at 45° even when the projectile is launched from a height above the ground.\nReason (R): For level ground, R = u² sin2θ/g, which is maximum at θ = 45°.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"R is true but A is false: when the launch point is above the landing level, the optimum angle is less than 45°, because the projectile gets extra time to fall. The 45° result holds only for level ground.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-kinematics-46", "question": "A particle moves 3 m due east and then 4 m due north. The magnitude of its displacement is:", "options": ["7 m", "1 m", "5 m", "12 m"], "answer": 2, "explanation": "Displacement joins the start to the end: √(3² + 4²) = 5 m. 7 m is the distance (path length), not the displacement.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-kinematics-47", "question": "The area under the acceleration–time graph of a particle over an interval gives its:", "options": ["change in velocity", "displacement", "change in acceleration", "average speed"], "answer": 0, "explanation": "Since dv = a dt, ∫a dt (the area under the a–t graph) equals the change in velocity. Displacement is the area under the v–t graph.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-kinematics-48", "question": "The position vector of a particle is r = (3t) i + (4t²) j metre, with t in seconds. Its speed at t = 1 s is:", "options": ["11 m/s", "5 m/s", "8 m/s", "√73 m/s ≈ 8.5 m/s"], "answer": 3, "explanation": "v = dr/dt = 3 i + 8t j; at t = 1 s, v = 3 i + 8 j, so speed = √(9 + 64) = √73 ≈ 8.5 m/s. 11 m/s wrongly adds the components.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-49", "question": "Two balls are dropped from rest from heights of 20 m and 80 m (g = 10 m/s², no air resistance). The ratio of their speeds on reaching the ground is:", "options": ["1 : 4", "1 : 2", "1 : 16", "1 : √2"], "answer": 1, "explanation": "v = √(2gh) gives 20 m/s and 40 m/s, a ratio of 1 : 2. Speed goes as √h, so 1 : 4 (the ratio of heights) is the trap.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-kinematics-50", "question": "A ball thrown vertically upward returns to the thrower's hand after 6 s (g = 10 m/s²). The maximum height it reached is:", "options": ["90 m", "45 m", "30 m", "180 m"], "answer": 1, "explanation": "Time of ascent = 3 s, so u = g × 3 = 30 m/s and H = u²/2g = 900/20 = 45 m. 90 m uses the full 6 s for the ascent.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-kinematics-51", "question": "Car A moves due north at 20 m/s and car B moves due east at 15 m/s. The magnitude of the velocity of A relative to B is:", "options": ["35 m/s", "5 m/s", "√175 m/s", "25 m/s"], "answer": 3, "explanation": "v_AB = v_A − v_B has components 20 m/s north and 15 m/s west, so |v_AB| = √(400 + 225) = 25 m/s. Perpendicular velocities never simply add or subtract.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-kinematics-52", "question": "A packet is released from an aeroplane flying horizontally at 100 m/s at a height of 500 m (g = 10 m/s², no air resistance). The horizontal distance it travels before hitting the ground is:", "options": ["1000 m", "500 m", "2000 m", "100√10 m"], "answer": 0, "explanation": "It keeps the plane's horizontal velocity. Time of fall t = √(2h/g) = √100 = 10 s, so horizontal distance = 100 × 10 = 1000 m.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-kinematics-53", "question": "Ball A is dropped from the top of a 45 m tower. One second later ball B is thrown vertically downward from the same point, and both reach the ground together (g = 10 m/s²). The speed with which B was thrown is:", "options": ["10 m/s", "15 m/s", "12.5 m/s", "22.5 m/s"], "answer": 2, "explanation": "A takes √(2 × 45/10) = 3 s, so B has 2 s: 45 = 2u + ½ × 10 × 2² = 2u + 20, giving u = 12.5 m/s.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-54", "question": "The trajectory of a projectile on level ground is y = x − x²/40, with x and y in metres (g = 10 m/s²). The speed of projection is:", "options": ["10√2 m/s", "40 m/s", "10 m/s", "20 m/s"], "answer": 3, "explanation": "Compare with y = x tanθ − gx²/(2u²cos²θ): tanθ = 1 so θ = 45°, and 10/(2u² × ½) = 1/40 gives u² = 400, u = 20 m/s (range 40 m, matching the root x = 40).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-55", "question": "A driver's reaction time is 0.5 s. At 20 m/s his car stops within a total distance of 50 m from the moment he sees an obstacle. With the same reaction time and braking deceleration, the total stopping distance at 30 m/s is:", "options": ["112.5 m", "105 m", "75 m", "90 m"], "answer": 1, "explanation": "At 20 m/s: 10 m during the reaction time, so braking distance 40 m and a = 400/80 = 5 m/s². At 30 m/s: 15 m + 900/10 = 90 m, total 105 m. 112.5 m scales the whole 50 m as v², ignoring that the reaction distance grows only as v.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-56", "question": "A particle moves on a circle of radius 1 m at a constant speed of 2 m/s. The magnitude of its average acceleration over one quarter of a revolution is:", "options": ["4 m/s²", "2√2 m/s²", "8√2/π m/s² ≈ 3.6 m/s²", "zero"], "answer": 2, "explanation": "After a quarter turn the velocity has turned 90°, so |Δv| = 2√2 m/s; time = (π/2 × 1)/2 = π/4 s. Average acceleration = 2√2 ÷ (π/4) = 8√2/π ≈ 3.6 m/s², less than the instantaneous centripetal value v²/r = 4 m/s².", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-57", "question": "The time t and position x of a particle moving along a straight line are related by t = √x + 3 (x in metres, t in seconds). The displacement of the particle when its velocity becomes zero is:", "options": ["zero", "3 m", "6 m", "9 m"], "answer": 0, "explanation": "x = (t − 3)², so v = 2(t − 3), which is zero at t = 3 s, where x = (3 − 3)² = 0. The particle started at x = 9 m and has returned to the origin.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-58", "question": "A lift is moving upward with a constant speed of 5 m/s. A boy inside throws a ball vertically upward at 10 m/s relative to the lift (g = 10 m/s²). The ball returns to his hand after:", "options": ["3 s", "1 s", "2 s", "1.33 s"], "answer": 2, "explanation": "A lift moving at constant velocity is an inertial frame, so relative to it the ball behaves normally: t = 2u/g = 2 × 10/10 = 2 s. The lift's 5 m/s does not matter; 3 s wrongly adds it.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-59", "question": "A stone is thrown horizontally from the top of a 20 m high tower and lands 40 m from the foot of the tower (g = 10 m/s²). Its velocity on hitting the ground is:", "options": ["20√2 m/s at 45° below the horizontal", "20 m/s at 45° below the horizontal", "20√2 m/s at 60° below the horizontal", "40 m/s vertically downward"], "answer": 0, "explanation": "Time of fall = √(2 × 20/10) = 2 s, so u = 40/2 = 20 m/s and v_y = gt = 20 m/s. Speed = √(20² + 20²) = 20√2 m/s, and since v_y = v_x the angle is 45° below the horizontal.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-kinematics-60", "question": "Two particles are thrown horizontally in opposite directions from the same point high above the ground, with speeds 3 m/s and 4 m/s (g = 10 m/s²). The distance between them when their velocities become perpendicular is:", "options": ["≈ 0.35 m", "≈ 1.73 m", "≈ 3.46 m", "≈ 2.42 m"], "answer": 3, "explanation": "Velocities are (3, −gt) and (−4, −gt); perpendicular when −12 + g²t² = 0, so t = √12/10 ≈ 0.346 s. Both fall equally, so their separation is horizontal: (3 + 4) × 0.346 ≈ 2.42 m. 0.35 m is the time in seconds, not the distance.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-kinematics-61", "question": "A ball is projected at 20√2 m/s at 45° above the horizontal towards a tall smooth vertical wall 30 m away (g = 10 m/s²). It rebounds elastically from the wall. Where does it land?", "options": ["At the point of projection", "20 m behind the point of projection (on the side away from the wall)", "10 m in front of the point of projection, between it and the wall", "50 m behind the point of projection"], "answer": 1, "explanation": "u_x = u_y = 20 m/s, so the flight time is 4 s and the horizontal path is 80 m whatever happens at the wall (an elastic hit only reverses u_x). It covers 30 m to the wall and 50 m back, landing 50 − 30 = 20 m behind the launch point.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-62", "question": "How many of the following statements are correct?\n(A) A particle can move with constant speed while its velocity changes.\n(B) A particle can have zero velocity and non-zero acceleration at an instant.\n(C) If the acceleration is directed opposite to the velocity, the speed decreases.\n(D) The magnitude of the average velocity over an interval can exceed the average speed.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A (uniform circular motion), B (top of a vertical throw) and C are correct. D is wrong: |displacement| ≤ distance, so the average velocity's magnitude can never exceed the average speed. Three are correct.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-kinematics-63", "question": "A particle is projected at 20 m/s up a plane inclined at 30° to the horizontal, in the vertical plane containing the line of greatest slope (g = 10 m/s²). The maximum possible range along the incline is:", "options": ["40 m", "80/3 m ≈ 26.7 m", "80 m", "20√3 m"], "answer": 1, "explanation": "Maximum range up an incline of angle α is u²/[g(1 + sin α)] = 400/(10 × 1.5) = 80/3 ≈ 26.7 m. 80 m uses (1 − sin α), which is the maximum range down the incline; 40 m is the level-ground value.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-kinematics-64", "question": "A speeding car passes a stationary police jeep at a constant 20 m/s. At that instant the jeep starts from rest with acceleration 2 m/s², but its top speed is 30 m/s, after which it moves uniformly. The jeep catches the car after:", "options": ["20 s", "15 s", "25 s", "22.5 s"], "answer": 3, "explanation": "The jeep reaches 30 m/s at t = 15 s, having covered 225 m while the car covered 300 m. Then 225 + 30(t − 15) = 20t gives t = 22.5 s. 20 s assumes unlimited acceleration (20t = t²).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-65", "question": "Ball A is dropped from the top of a 30 m tower. At the same instant ball B, on the ground 40 m from the foot of the tower, is projected aiming directly at A (g = 10 m/s²). The minimum speed of B for the two to collide before A reaches the ground is about:", "options": ["20.4 m/s", "16.3 m/s", "12.2 m/s", "25 m/s"], "answer": 0, "explanation": "Both fall equally, so relative to free fall B moves straight along the 50 m line of sight: collision time = 50/u. A lands after √(60/10) = √6 ≈ 2.45 s, so u ≥ 50/2.45 ≈ 20.4 m/s. 16.3 m/s uses only the 40 m horizontal gap.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-kinematics-66", "question": "The velocity of a particle rises uniformly from 0 to 20 m/s in the first 4 s, stays at 20 m/s for the next 6 s, and then decreases uniformly to −10 m/s over the following 6 s. Over these 16 s its displacement and distance travelled are:", "options": ["210 m and 210 m", "190 m and 190 m", "190 m and 210 m", "200 m and 210 m"], "answer": 2, "explanation": "Areas: 0–4 s: 40 m; 4–10 s: 120 m; the velocity falls at 5 m/s² and crosses zero at t = 14 s, giving +40 m (10–14 s) and −10 m (14–16 s). Displacement = 200 − 10 = 190 m; distance = 200 + 10 = 210 m.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-67", "question": "Assertion (A): A particle in uniform circular motion moves with constant acceleration.\nReason (R): The magnitude of its centripetal acceleration, v²/r, stays constant.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false: the acceleration always points to the centre, so its direction keeps changing and it is not a constant vector. R is true: only the magnitude v²/r is constant.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-kinematics-68", "question": "A particle moving in a straight line at 20 m/s experiences a retardation proportional to its speed, a = −0.5v (SI units). The total distance it covers while (asymptotically) coming to rest is:", "options": ["20 m", "80 m", "infinite, since it never stops", "40 m"], "answer": 3, "explanation": "v dv/dx = −0.5v gives dv/dx = −0.5, so v falls linearly with distance: v = 20 − 0.5x, reaching zero at x = 40 m. The speed decays exponentially in time, but the distance converges to the finite value v₀/k.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-kinematics-69", "question": "Match the motion (List I) with its acceleration (List II), all in SI units.\nList I: (P) x = 3t + 2; (Q) v = 4t; (R) x = 5 sin t; (S) v² = 4x.\nList II: (1) zero; (2) 4 m/s²; (3) 2 m/s²; (4) equal to −x at every instant.", "options": ["P-1, Q-3, R-4, S-2", "P-1, Q-2, R-4, S-3", "P-2, Q-1, R-3, S-4", "P-1, Q-2, R-3, S-4"], "answer": 1, "explanation": "P: v = 3, a = 0. Q: a = dv/dt = 4. R: a = −5 sin t = −x. S: differentiating v² = 4x gives 2v a = 4v, so a = 2 m/s². Hence P-1, Q-2, R-4, S-3.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-70", "question": "A boat crosses a 200 m wide river in the least possible time, 40 s, and in doing so drifts 120 m downstream. If it instead crosses along the shortest path (straight across), it takes:", "options": ["40 s", "66.7 s", "50 s", "62.5 s"], "answer": 2, "explanation": "Least time means heading straight across: boat speed = 200/40 = 5 m/s and river speed = 120/40 = 3 m/s. For the straight path the resultant across is √(5² − 3²) = 4 m/s, so t = 200/4 = 50 s.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-kinematics-71","question":"A hot-air balloon is rising at 10 m/s. When it is 40 m above the ground, a stone is thrown downward from it at 20 m/s relative to the balloon (g = 10 m/s²). The stone reaches the ground after:","options":["2 s","1.2 s","4 s","2.8 s"],"answer":0,"explanation":"Relative to the ground the stone starts at 20 − 10 = 10 m/s downward. −40 = −10t − 5t² gives t² + 2t − 8 = 0, so t = 2 s. Using 20 m/s downward without the balloon's velocity gives about 1.2 s; dropping the stone from the rising balloon (10 m/s upward) gives 4 s.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-kinematics-72","question":"A ball is thrown vertically upward at 25 m/s (g = 10 m/s²). During the 3rd second of its motion, its displacement and the distance it covers are respectively:","options":["0 and 0","0 and 2.5 m","2.5 m and 2.5 m","5 m and 5 m"],"answer":1,"explanation":"sₙ = u − g(2n − 1)/2 = 25 − 25 = 0 for n = 3. But the ball is at the top at t = 2.5 s, so it rises ½ × 10 × 0.5² = 1.25 m and falls back 1.25 m: distance 2.5 m. The nth-second formula gives displacement, not distance, whenever the motion reverses within that second.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-kinematics-73","question":"A man 1.5 m tall walks away from a lamp post at a steady 1.5 m/s. The lamp is 6 m above the ground. The rate at which the length of his shadow increases is:","options":["2.0 m/s","1.5 m/s","0.5 m/s","0.375 m/s"],"answer":2,"explanation":"By similar triangles, with x = man's distance and s = shadow length, s/1.5 = (x + s)/6, so s = x/3 and ds/dt = 1.5/3 = 0.5 m/s. The tip of the shadow moves at dx/dt + ds/dt = 2.0 m/s, which is the trap.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-kinematics-74","question":"Swimmer A and swimmer B both swim at 5 m/s relative to the water in a river flowing at 3 m/s. A swims across the river to the point directly opposite and back; B swims the same distance downstream along the bank and back. The ratio of B's total time to A's total time is:","options":["0.80","1.56","1.00","1.25"],"answer":3,"explanation":"A must aim upstream so that the resultant is across: speed √(5² − 3²) = 4 m/s, so t_A = 2d/4 = d/2. B: t_B = d/8 + d/2 = 5d/8. Ratio = (5d/8)/(d/2) = 1.25. The across-and-back trip is always faster, which is why 0.80 and 1.00 are wrong.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-75","question":"A man stands on a trolley moving at 5 m/s on a straight level track. He throws a ball at 10 m/s relative to the trolley so that, to an observer on the ground, the ball moves straight up and down (g = 10 m/s²). The ball is thrown, relative to the trolley, at:","options":["60° above the horizontal, pointing backward, and it rises 3.75 m","30° above the horizontal, pointing backward, and it rises 1.25 m","60° above the horizontal, pointing forward, and it rises 3.75 m","Straight up, and it rises 5 m"],"answer":0,"explanation":"For zero horizontal velocity on the ground, the relative horizontal component must cancel the trolley's 5 m/s: 10 cos θ = 5 backward, so θ = 60°. The vertical component 10 sin 60° = 5√3 m/s gives h = 75/20 = 3.75 m. Throwing straight up relative to the trolley would leave it moving forward at 5 m/s.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-76","question":"A particle moves on a circle of radius 4 m with speed v = 2t (SI units), starting from rest. By the time its total acceleration makes an angle of 45° with its velocity, the distance it has travelled along the circle is:","options":["4 m","2 m","8 m","√2 m"],"answer":1,"explanation":"a_t = dv/dt = 2 m/s² and a_c = v²/R = 4t²/4 = t². At 45°, a_c = a_t: t² = 2, t = √2 s. Distance s = ∫2t dt = t² = 2 m. Giving the time (√2) instead of the distance is the slip.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-77","question":"A particle starts from rest. Its acceleration is 4 m/s² for the first 2 s and then −2 m/s² for the next 6 s. The distance it covers in the 8 s is:","options":["24 m","20 m","28 m","32 m"],"answer":2,"explanation":"v(2) = 8 m/s and s = 8 m. It then slows down, stopping at t = 2 + 4 = 6 s after another 16 m, and moves backward for 2 s, reaching 4 m/s, a further 4 m. Distance = 8 + 16 + 4 = 28 m, while the displacement is 20 m (the trap).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-78","question":"Two balls are projected at the same instant from the same point on level ground, each at 50 m/s, one at 37° and the other at 53° above the horizontal (g = 10 m/s², sin 37° = 0.6). Their separation 2 s after projection is:","options":["10√2 m","20 m","40√2 m","20√2 m"],"answer":3,"explanation":"Both have the same acceleration g, so their relative velocity stays constant: (40, 30) − (30, 40) = (10, −10) m/s, of magnitude 10√2 m/s. Separation = 10√2 × 2 = 20√2 ≈ 28.3 m. Both balls are still in the air (the lower one lands at 6 s).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-79","question":"A ball is dropped from a height of 80 m. At the same instant a second ball is thrown vertically upward from the ground directly below it (g = 10 m/s²). If the balls meet just as the second ball reaches its highest point, its speed of projection was:","options":["20√2 m/s","20 m/s","40√2 m/s","40 m/s"],"answer":0,"explanation":"Relative speed is constant (the same g acts on both), so they meet at t = 80/u. The second ball is at its top at t = u/g. Equating: u² = 80g = 800, so u = 20√2 ≈ 28.3 m/s; they meet 40 m up. 40 m/s is √(2gH), the speed for the second ball just to reach 80 m.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "phy-kinematics-80", "question": "A projectile is launched from level ground at 20 m/s at 60° above the horizontal (g = 10 m/s²). The radius of curvature of its path at the point of launch is:", "options": ["10 m", "80 m", "40 m", "20 m"], "answer": 1, "explanation": "Radius of curvature = v²/a_n, where a_n is the component of g perpendicular to the velocity: g cos 60° = 5 m/s². R = 400/5 = 80 m. 10 m is the radius at the highest point, (u cos θ)²/g.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-kinematics-81", "question": "A ball is thrown from the ground so that it just passes through a point 40 m away horizontally and 30 m above the launch level (g = 10 m/s²). The least launch speed that can do this is:", "options": ["10√7 m/s", "10√10 m/s", "20√2 m/s", "10√5 m/s"], "answer": 2, "explanation": "The least speed to reach a point at distance r = √(40² + 30²) = 50 m and height h = 30 m is given by u² = g(h + r) = 10(30 + 50) = 800, so u = 20√2 ≈ 28.3 m/s. Using g(h + x) = 700 gives 10√7, which ignores the true distance to the point.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-kinematics-82","question":"A ball is projected at 10 m/s from a point on a long plane inclined at 30° to the horizontal, in the vertical plane through the line of greatest slope, pointing down the incline (g = 10 m/s²). The maximum possible range along the incline is:","options":["40 m","6.67 m","10 m","20 m"],"answer":3,"explanation":"Down an incline of angle α, R_max = u²/[g(1 − sin α)] = 100/(10 × 0.5) = 20 m. The up-the-incline formula u²/[g(1 + sin α)] gives 6.67 m; level ground gives 10 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-kinematics-83", "question": "Ball A is projected from the ground at 20 m/s at an angle θ above the horizontal (sin θ = 0.8) towards a 32 m high tower whose foot is 32 m away. At the same instant ball B is thrown horizontally at 4 m/s from the top of the tower towards A (g = 10 m/s²). The two balls collide at a height above the ground of:", "options": ["12 m", "32 m", "20 m", "16 m"], "answer": 0, "explanation": "In the freely falling frame both move uniformly. A's velocity relative to B is (12 + 4, 16) = (16, 16) m/s, pointing straight at B (32 m across, 32 m up), so they collide at t = 32/16 = 2 s. Height = 32 − ½ × 10 × 2² = 12 m (A: 16 × 2 − 20 = 12 m, check). 32 m forgets that both fall during the 2 s.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-kinematics-84","question":"Three particles start together from the corners of an equilateral triangle of side 30 m. Each moves at a constant speed of 5 m/s, always heading straight towards the particle at the next corner (taken in the same sense). They meet after:","options":["6 s","4 s","2 s","3 s"],"answer":1,"explanation":"The rate at which each separation shrinks is v − v cos 120° = v(1 + 1/2) = 3v/2 = 7.5 m/s, and this stays constant by symmetry. Time = 30/7.5 = 4 s (each particle travels 20 m). 6 s (= a/v) ignores that the target also moves towards the chaser.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-85","question":"A particle moving along a straight line at 16 m/s is subjected to a retardation a = 2√v (SI units, v = speed). The distance it covers before stopping is:","options":["32 m","16 m","64/3 m","128/3 m"],"answer":2,"explanation":"dv/dt = −2√v gives √v = 4 − t, so it stops at t = 4 s with v = (4 − t)². Distance = ∫₀⁴ (4 − t)² dt = 64/3 ≈ 21.3 m. Using the average speed 8 m/s over 4 s gives 32 m, which wrongly assumes uniform retardation.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-kinematics-86", "question": "A particle moving along the x-axis from the origin has a velocity that depends on its position as v = 10 − 0.5x (SI units). The time it takes to go from x = 0 to x = 10 m is:", "options": ["1.33 s", "2.0 s", "It never reaches x = 10 m", "2 ln 2 s ≈ 1.39 s"], "answer": 3, "explanation": "dx/dt = 10 − 0.5x gives x = 20(1 − e^(−t/2)). Setting x = 10: e^(−t/2) = 1/2, so t = 2 ln 2 ≈ 1.39 s. The particle only approaches x = 20 m asymptotically, but it does pass x = 10 m. 1.33 s uses the average of 10 and 5 m/s, which is wrong because the acceleration is not uniform.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-kinematics-87","question":"A particle is projected from the foot of a plane inclined at 30° to the horizontal, in the vertical plane through the line of greatest slope, at 10√7 m/s. It strikes the incline at right angles (g = 10 m/s²). The distance from the point of projection to where it strikes, measured along the incline, is:","options":["40 m","80 m","20 m","40√3 m"],"answer":0,"explanation":"Take axes along and perpendicular to the incline, with β the angle of projection above the incline. Striking normally means the velocity along the incline is zero on impact, which requires tan β = cot 30°/2 = √3/2 (so sin β = √3/√7, cos β = 2/√7). T = 2u sin β/(g cos 30°) = 4 s; range = u cos β T − ½ g sin 30° T² = 80 − 40 = 40 m. 80 m forgets the slowing along the incline.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-88","question":"A projectile is launched from level ground at 20 m/s at 60° above the horizontal (g = 10 m/s²). For how long during its flight does its velocity make an angle of less than 45° with the horizontal?","options":["√3 s","2 s","(√3 − 1) s","2√3 s"],"answer":1,"explanation":"The angle is below 45° while |v_y| < v_x = 10 m/s. v_y = 10√3 − 10t, so this holds from t = √3 − 1 to t = √3 + 1: an interval of 2 s (out of a total flight of 2√3 ≈ 3.46 s). √3 − 1 is only the moment it first drops below 45°.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-89","question":"A steady wind gives a ball a constant horizontal acceleration of 5 m/s² directed opposite to the horizontal component of its launch velocity. At what angle above the horizontal must the ball be thrown so that it lands back at the thrower's feet (g = 10 m/s²)?","options":["tan⁻¹(1/2)","45°","tan⁻¹(2)","tan⁻¹(4)"],"answer":2,"explanation":"Time of flight T = 2u sin θ/g. Horizontal displacement zero: u cos θ T − ½aT² = 0, so u cos θ = aT/2 = a u sin θ/g, giving tan θ = g/a = 2. The answer does not depend on the speed.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-kinematics-90", "question": "Assertion (A): A particle moving with constant speed can have a non-zero acceleration only if that acceleration is perpendicular to its velocity.\nReason (R): For any motion, d(v²)/dt = 2 (vector v) · (vector a).", "options": ["Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "v² = v · v, so d(v²)/dt = 2 v · a. Constant speed means v · a = 0: either a = 0 or a ⊥ v. R is the exact reason for A.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-kinematics-91","question":"A river 60 m wide flows at 5 m/s. A boatman wants to go from point A on one bank to point B on the other bank, 80 m downstream of the point directly opposite A, travelling along the straight line AB. The least speed relative to the water with which he can do this, and the time taken at that speed, are:","options":["4 m/s and 15 s","3.75 m/s and 16 s","3 m/s and 20 s","3 m/s and 25 s"],"answer":3,"explanation":"AB makes an angle φ with the flow where tan φ = 60/80, so sin φ = 0.6. The boat's velocity must turn the river velocity onto AB; its least value is perpendicular to AB: u = 5 sin φ = 3 m/s. The resultant along AB is 5 cos φ = 4 m/s, and AB = 100 m, so t = 25 s. 3 m/s and 20 s wrongly takes the crossing speed as 3 m/s across a 60 m river.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-kinematics-92", "question": "A stone is projected at 10 m/s from the top of a tower 15 m high (g = 10 m/s²). The greatest horizontal distance from the foot of the tower at which it can land, and the angle of projection for it, are:", "options": ["20 m at tan⁻¹(1/2) above the horizontal", "18.2 m at 45° above the horizontal", "10 m at 45° above the horizontal", "20 m at 45° above the horizontal"], "answer": 0, "explanation": "From height h, R_max = (u/g)√(u² + 2gh) = 1 × √(100 + 300) = 20 m, reached when tan θ = u/√(u² + 2gh) = 10/20 = 1/2. At 45° the stone lands at only about 18.2 m: 45° is optimal only when launch and landing are at the same level.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-kinematics-93","question":"The position vector of a particle is r = t² i + 3t j metre, with t in seconds. The radius of curvature of its path at t = 1 s is about:","options":["6.5 m","7.8 m","4.3 m","2.2 m"],"answer":1,"explanation":"v = (2t, 3) and a = (2, 0); at t = 1 s, v = (2, 3) with |v| = √13, and |v × a| = |2·0 − 3·2| = 6. R = |v|³/|v × a| = 13^(3/2)/6 ≈ 46.9/6 ≈ 7.8 m. Using v²/|a| = 13/2 = 6.5 m treats the whole of a as normal, which is wrong because a has a component along v.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-94","question":"Ball P is dropped from a height of 60 m. At the same instant ball Q is thrown vertically upward at 15 m/s from the ground directly below it; Q does not bounce (g = 10 m/s²). Which statement is correct?","options":["They meet after 4 s, 20 m above the ground","They meet after 4 s, exactly at ground level","They do not meet in the air: Q is back on the ground at 3 s, before they could meet","They meet after 2 s, 40 m above the ground"],"answer":2,"explanation":"The relative speed is 15 m/s, so a meeting in the air would need t = 60/15 = 4 s. But Q lands at 2 × 15/10 = 3 s, and P would by then be at 60 − 45 = 15 m; P lands at √12 ≈ 3.46 s. So they never meet in flight. The 4 s answer misses the hidden condition that Q must still be in the air.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-95","question":"A car can accelerate at 2 m/s² and brake at 4 m/s², and its speed must not exceed 20 m/s. The least time in which it can cover 300 m, starting and ending at rest, is:","options":["21.2 s","25.0 s","15.0 s","22.5 s"],"answer":3,"explanation":"Without a speed limit the best plan peaks at v = √(2d·αβ/(α + β)) = √800 ≈ 28.3 m/s (time √450 ≈ 21.2 s), which breaks the limit. So: accelerate to 20 m/s in 10 s (100 m), brake in 5 s (50 m), and cruise the remaining 150 m in 7.5 s. Total = 22.5 s. 21.2 s ignores the speed limit.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-kinematics-96","question":"A particle moving along the x-axis has velocity v = 3t² − 12 (SI units). The distance (not displacement) it covers between t = 0 and t = 3 s is:","options":["25 m","9 m","16 m","23 m"],"answer":3,"explanation":"Velocity is zero at t = 2 s, so the particle turns back there. With x = t³ − 12t: x(0) = 0, x(2) = −16 m, x(3) = −9 m. Distance = 16 + 7 = 23 m, while the displacement is only 9 m.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-kinematics-97","question":"A particle moves along a semicircle of radius R from one end of a diameter to the other at constant speed. The ratio (average speed)/(magnitude of average velocity) for this motion is:","options":["π","2/π","π/2","1"],"answer":2,"explanation":"Average speed = path length/time = πR/t, while |average velocity| = displacement/time = 2R/t. Their ratio is πR/2R = π/2, independent of R and the speed.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-kinematics-98","question":"A projectile is launched from level ground at 20 m/s. At the highest point of its path its speed is exactly half its launch speed (g = 10 m/s²). Its horizontal range is:","options":["40 m","20√3 m","10√3 m","20 m"],"answer":1,"explanation":"At the top only the horizontal component u cos θ remains, so cos θ = 1/2 and θ = 60°. Range R = u² sin 2θ/g = 400 × (√3/2)/10 = 20√3 m ≈ 34.6 m.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-kinematics-99","question":"Two balls are projected simultaneously from the same point on level ground, each at 20 m/s, one at 30° and the other at 60° above the horizontal, in the same vertical plane (g = 10 m/s²). Their separation at t = 2 s, just as the first ball lands, is about:","options":["20.7 m","10.4 m","41.4 m","14.6 m"],"answer":0,"explanation":"Both have the same acceleration g, so their relative velocity is constant: |u₁ − u₂| = 2u sin(15°) = 40 × 0.2588 ≈ 10.35 m/s. Starting together, the separation grows linearly: 10.35 × 2 ≈ 20.7 m.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-kinematics-100","question":"A motorboat moving at 20 m/s switches off its engine. Water resistance then produces a retardation a = 0.05v² (SI units). The distance it covers while its speed falls to 10 m/s is:","options":["20 ln 2 m ≈ 13.9 m","10 m","15 m","20 m"],"answer":0,"explanation":"Write a = v dv/dx = −kv², so dv/v = −k dx and x = (1/k) ln(v₀/v). With k = 0.05 m⁻¹ and v₀/v = 2, x = 20 ln 2 ≈ 13.9 m.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-kinematics-101","question":"Ship A moves due east at 20 m/s. At t = 0, ship B is 200 m due east of A and moves due north at 15 m/s. The minimum separation between the ships and the time at which it occurs are:","options":["96 m at t = 6.4 s","160 m at t = 8 s","120 m at t = 8 s","120 m at t = 6.4 s"],"answer":3,"explanation":"In A's frame, B moves with velocity (−20, 15) m/s, of magnitude 25 m/s, starting from (200, 0). Closest approach = |r × v|/|v| = (200 × 15)/25 = 120 m. It occurs at t = (r·(−v))/v² = (200 × 20)/625 = 6.4 s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-102","question":"A ball is projected at 20 m/s from a point on a long plane inclined at 30° to the horizontal, in the vertical plane containing the line of greatest slope, so that it lands DOWN the slope (g = 10 m/s²). The maximum possible range along the incline is:","options":["26.7 m","40 m","80 m","46.2 m"],"answer":2,"explanation":"For an incline of angle α, the maximum range down the slope is u²/[g(1 − sin α)] (and up the slope u²/[g(1 + sin α)] ≈ 26.7 m). Here 400/(10 × 0.5) = 80 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-103","question":"A small ball is dropped from rest from a height of 5 m above a fixed, smooth plane inclined at 30° to the horizontal. It rebounds elastically. The distance along the incline between its first and second impacts is (g = 10 m/s²):","options":["10 m","20 m","40 m","17.3 m"],"answer":1,"explanation":"Impact speed is 10 m/s. Along the incline axes: perpendicular velocity 10 cos 30° reverses, perpendicular deceleration is g cos 30°, so the time between impacts is 2 s. Along the slope the ball starts with 10 sin 30° = 5 m/s and accelerates at g sin 30° = 5 m/s²: s = 5 × 2 + ½ × 5 × 4 = 20 m (= 8h sin α).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-104","question":"The velocity–time graph of a particle, drawn with 1 unit = 1 s on the time axis and 1 unit = 1 m/s on the velocity axis, is a semicircle above the time axis from t = 0 to t = 4 s. The distance travelled in these 4 s is:","options":["4π m","2π m","8 m","π m"],"answer":1,"explanation":"Distance equals the area under the speed–time curve. The semicircle has radius 2 units, so the area is ½π(2)² = 2π, i.e. 2π m ≈ 6.28 m.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-kinematics-105","question":"A particle starts from rest on a circle and moves with constant tangential acceleration. At the instant its net acceleration makes 45° with its velocity, the angle it has swept about the centre is:","options":["0.5 rad","1 rad","π/4 rad","0.25 rad"],"answer":0,"explanation":"At 45°, centripetal = tangential: v²/R = aₜ. Since v² = 2aₜs, this gives 2aₜs/R = aₜ, so s = R/2 and the angle swept is s/R = 0.5 rad, independent of R and aₜ.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-106","question":"A target hangs at the point (40 m, 30 m) relative to a gun at the origin. The target is released from rest, and 0.2 s LATER the gun fires a bullet at 50 m/s aimed at the target's original position (g = 10 m/s²). When the bullet reaches x = 40 m, it is:","options":["exactly at the target","2.2 m below the target","1.2 m above the target","2.2 m above the target"],"answer":3,"explanation":"The bullet's horizontal speed is 50 × (4/5) = 40 m/s, so it reaches x = 40 m after 1 s, having fallen 5 m below the line of sight (y = 25 m). The target has then fallen for 1.2 s: ½ × 10 × 1.44 = 7.2 m, to y = 22.8 m. The bullet passes 2.2 m above it; only a simultaneous release gives a hit.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-107","question":"A particle moving along the x-axis has velocity v = (4 − x) m/s, where x is in metres, and starts from x = 0 at t = 0. The time it takes to reach x = 2 m is:","options":["1 s","0.5 s","ln 2 s ≈ 0.69 s","2 ln 2 s ≈ 1.39 s"],"answer":2,"explanation":"dt = dx/(4 − x), so t = ln[4/(4 − x)]. At x = 2 m, t = ln 2 ≈ 0.69 s. (The particle never actually reaches x = 4 m.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-kinematics-108","question":"A ball is thrown vertically up at 20 m/s. At the instant it reaches its highest point, a second ball is thrown up from the same point at 20 m/s (g = 10 m/s²). The two balls meet at a height of:","options":["5 m","10 m","15 m","17.5 m"],"answer":2,"explanation":"H = u²/2g = 20 m. Relative to each other the balls approach at a constant 20 m/s, so they meet after 20/20 = 1 s. The first ball has then fallen ½ × 10 × 1² = 5 m, so they meet at 15 m (= 3H/4).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-kinematics-109","question":"A 5 m ladder leans against a smooth vertical wall. Its foot is pulled away from the wall along the floor at a steady 3 m/s. When the foot is 3 m from the wall, the top of the ladder slides down at:","options":["4 m/s","2.25 m/s","3 m/s","1.8 m/s"],"answer":1,"explanation":"x² + y² = 25 gives x ẋ + y ẏ = 0. With x = 3 m, y = 4 m and ẋ = 3 m/s: ẏ = −(3 × 3)/4 = −2.25 m/s, i.e. the top moves down at 2.25 m/s.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-kinematics-110","question":"In 2 s the velocity of a particle changes from (3î + 4ĵ) m/s to (−4î + 3ĵ) m/s. The magnitude of its average acceleration over this interval is:","options":["2.5√2 m/s² ≈ 3.54 m/s²","2.5 m/s²","zero, as the speed is unchanged","5 m/s²"],"answer":0,"explanation":"Average acceleration = Δv/Δt = (−7î − ĵ)/2. |Δv| = √50 = 5√2 m/s, so the magnitude is 5√2/2 ≈ 3.54 m/s². Equal speeds do not mean zero average acceleration, because the direction changed.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-kinematics-111","question":"A projectile is launched at 20 m/s at 60° above the horizontal (g = 10 m/s²). After how long is its velocity perpendicular to its initial velocity?","options":["Never during its flight","2√3 s ≈ 3.46 s","√3 s ≈ 1.73 s","4/√3 s ≈ 2.31 s"],"answer":3,"explanation":"v·u = 0 gives u² − g t u sin θ = 0, so t = u/(g sin θ) = 20/(10 × √3/2) = 4/√3 ≈ 2.31 s. This is less than the flight time 2√3 s, so it happens in flight (it would not for launch angles below 45°).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-112","question":"A ball is projected at 20 m/s at 60° above the horizontal (g = 10 m/s²). The magnitude of its average velocity between launch and the highest point is:","options":["10√3 m/s","10 m/s","20 m/s","5√7 m/s ≈ 13.2 m/s"],"answer":3,"explanation":"Over this interval the horizontal component is constant at 10 m/s, and the vertical one falls uniformly from 10√3 to 0, averaging 5√3 m/s. Magnitude = √(100 + 75) = 5√7 ≈ 13.2 m/s.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-kinematics-113","question":"A rabbit runs along a straight line at a constant 3 m/s. At t = 0 a dog, 32 m from the rabbit along the perpendicular to the rabbit's path, starts chasing it at a constant 5 m/s, always heading straight at the rabbit. The dog catches the rabbit after:","options":["6.4 s","8 s","10 s","16 s"],"answer":2,"explanation":"Let θ be the angle between the rabbit's velocity and the dog-to-rabbit line. The gap closes at u − v cos θ, so ∫(u − v cos θ)dt = d. Along the rabbit's path the dog must cover the rabbit's run: ∫u cos θ dt = vT. Eliminating ∫cos θ dt gives uT − v²T/u = d, so T = ud/(u² − v²) = 160/16 = 10 s. Note 6.4 s (d/u) ignores the rabbit's motion and 16 s (d/(u − v)) assumes a head-on chase.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-114","question":"A ball is dropped from a height of 20 m onto a hard floor. The coefficient of restitution is 0.5. The total distance it travels before coming to rest is:","options":["40 m","33.3 m","26.7 m","60 m"],"answer":1,"explanation":"Each rebound height is e² = 1/4 of the previous one, and each rebound height is covered twice. Total = h + 2h(e² + e⁴ + …) = h(1 + e²)/(1 − e²) = 20 × 1.25/0.75 ≈ 33.3 m.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-kinematics-115","question":"A river 80 m wide has a current that increases linearly from zero at each bank to 6 m/s at mid-stream. A boat that moves at 4 m/s relative to the water keeps its heading perpendicular to the banks. How far downstream does it land?","options":["60 m","120 m","30 m","90 m"],"answer":0,"explanation":"The crossing takes 80/4 = 20 s, spent uniformly across the width. The downstream drift = ∫ u dt; as y increases at a constant rate, this is (average current) × time = 3 × 20 = 60 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-116","question":"A particle starts from rest. Its acceleration increases linearly from 0 to 4 m/s² during the first 2 s and then decreases linearly back to 0 at t = 4 s. Its displacement at t = 4 s is:","options":["16 m","32 m","12 m","18.7 m"],"answer":0,"explanation":"For 0–2 s, a = 2t gives v = t², x = 8/3 m, and v(2) = 4 m/s. For the next 2 s (s = t − 2), v = 4 + 4s − s², so Δx = 8 + 8 − 8/3 = 40/3 m. Total = 8/3 + 40/3 = 16 m (final speed 8 m/s).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-117","question":"A particle moves in the xy-plane with x = 4 cos(πt/2) and y = 3 sin(πt/2) (metres, seconds). At the instants when its speed is maximum, the magnitude of its acceleration is:","options":["zero","π² m/s²","3π/2 m/s²","3π²/4 m/s²"],"answer":3,"explanation":"Acceleration = −(π/2)² r, always toward the origin. Speed² = (π/2)²(16 sin² + 9 cos²) is maximum when sin = ±1, i.e. at (0, ±3). There |a| = (π²/4) × 3 = 3π²/4 ≈ 7.4 m/s².","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-118","question":"Two runners start together from the same point on a circular track of radius 10 m and run in the same direction at constant speeds of 4 m/s and 6 m/s. They are next side by side after:","options":["20π s","2π s","10π s ≈ 31.4 s","4π s"],"answer":2,"explanation":"Relative to the slower runner, the faster one gains at 2 m/s and must gain a full lap of 2π × 10 = 20π m. Time = 20π/2 = 10π s ≈ 31.4 s.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-kinematics-119","question":"A small lamp is fixed at a point. A ball is projected horizontally from the lamp's position at 10 m/s, straight towards a vertical wall 20 m away (g = 10 m/s²). Before the ball hits the wall, the shadow of the ball on the wall moves:","options":["downward at 10 m/s with increasing speed","downward at a constant 10 m/s","downward at a constant 5 m/s","downward at a constant 20 m/s"],"answer":1,"explanation":"The ball is at (ut, ½gt²) below the lamp. By similar triangles the shadow is at depth d·(½gt²)/(ut) = (gd/2u)t on the wall, which is linear in t. So the shadow moves uniformly at gd/2u = 10 × 20/20 = 10 m/s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-120","question":"A swimmer (2.5 m/s relative to water) wants to reach the point directly opposite on a river 150 m wide flowing at 2 m/s. Plan P: head perpendicular to the current, then walk back along the bank at 2 m/s. Plan Q: head upstream at the angle that takes her straight across. Which is correct?","options":["Plan P is faster by 20 s","Plan Q is faster by 20 s","Both take 100 s","Plan Q is faster by 40 s"],"answer":1,"explanation":"Plan P: crossing takes 150/2.5 = 60 s with drift 2 × 60 = 120 m, walked back in 60 s, total 120 s. Plan Q: resultant speed across = √(2.5² − 2²) = 1.5 m/s, time 150/1.5 = 100 s. Q wins by 20 s.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-kinematics-121","question":"Which of the following is necessarily true for a particle moving with constant speed?","options":["Its acceleration, if non-zero, is perpendicular to its velocity","Its acceleration is zero","Its velocity is constant","Its path is a straight line"],"answer":0,"explanation":"d(v·v)/dt = 2v·a = 0 when the speed is constant, so any acceleration must be perpendicular to the velocity. A particle in uniform circular motion has constant speed, a changing velocity, a non-zero acceleration and a curved path.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-kinematics-122","question":"A projectile on level ground has a horizontal range of 40√3 m and a maximum height of 10 m (g = 10 m/s²). Its speed of projection is:","options":["10√6 m/s","20 m/s","40 m/s","20√2 m/s"],"answer":3,"explanation":"H/R = tan θ/4, so tan θ = 4 × 10/(40√3) = 1/√3 and θ = 30°. Then H = u² sin²θ/2g gives 10 = u² × (1/4)/20, so u² = 800 and u = 20√2 ≈ 28.3 m/s.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-kinematics-123","question":"A particle leaves the origin with velocity 4 m/s along +x and has a constant acceleration of 2 m/s² along +y. When its velocity makes 45° with the x-axis, its distance from the origin is:","options":["4√2 m","8 m","4√5 m ≈ 8.94 m","12 m"],"answer":2,"explanation":"45° means vᵧ = vₓ = 4 m/s, so t = 4/2 = 2 s. Then x = 4 × 2 = 8 m and y = ½ × 2 × 4 = 4 m, so the distance is √80 = 4√5 ≈ 8.94 m.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-kinematics-124","question":"From the top of a high cliff, one stone is thrown vertically upward at 20 m/s and, at the same instant, another is thrown horizontally at 15 m/s. Neglecting air resistance, their separation after 2 s is:","options":["30 m","70 m","50 m","20 m"],"answer":2,"explanation":"Both stones have the same acceleration g, so their relative velocity is constant: |(0, 20) − (15, 0)| = 25 m/s. Starting together, the separation after 2 s is 25 × 2 = 50 m; gravity drops out entirely.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-kinematics-125","question":"A man walks up a stationary escalator in 60 s, and stands still on the moving (upward) escalator to be carried up in 40 s. If he instead walks DOWN, at his usual pace, on the upward-moving escalator, starting from the top step:","options":["he reaches the bottom in 120 s","he never reaches the bottom; he is carried back up through the top in 120 s","he reaches the bottom in 24 s","he stays at the same place"],"answer":1,"explanation":"Speeds (in escalator lengths per second): walking 1/60, escalator 1/40. Walking down on the up-escalator gives a net upward 1/40 − 1/60 = 1/120 per second. He is carried upward, so he cannot reach the bottom; starting at the bottom he would take 120 s to be carried a full length.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-126","question":"A car covers the first third of a journey at 11 m/s, the second third at 22 m/s and the last third at 33 m/s. Its average speed for the whole journey is:","options":["18 m/s","22 m/s","20 m/s","16.5 m/s"],"answer":0,"explanation":"For equal distances the average speed is the harmonic mean: 3/(1/11 + 1/22 + 1/33) = 3/(6/66 + 3/66 + 2/66) = 3 × 66/11 = 18 m/s. 22 m/s is the arithmetic mean, which would apply to equal time intervals.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-kinematics-127","question":"A ball is projected from the foot of a plane inclined at 45° to the horizontal, up the line of greatest slope, at an angle φ measured FROM THE INCLINE. It strikes the incline at right angles. Then tan φ equals:","options":["1","2","1/√2","1/2"],"answer":3,"explanation":"Take axes along and perpendicular to the incline. Time of flight T = 2u sin φ/(g cos α). Hitting perpendicularly means the along-slope velocity is zero then: u cos φ = g sin α · T. Dividing gives cot φ = 2 tan α, so tan φ = cot α/2 = 1/2 for α = 45°.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-128","question":"A ball must be thrown from the ground so that it passes through a point 30 m away horizontally and 40 m above the launch point (g = 10 m/s²). The minimum launch speed that makes this possible is:","options":["10√5 m/s ≈ 22.4 m/s","10√10 m/s ≈ 31.6 m/s","20√2 m/s ≈ 28.3 m/s","30 m/s"],"answer":3,"explanation":"Minimising u² over the launch angle for a target at (x, y) gives u²_min = g[y + √(x² + y²)]. Here √(30² + 40²) = 50, so u² = 10(40 + 50) = 900 and u = 30 m/s. (The bounding 'parabola of safety' passes through the point.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-kinematics-129","question":"The position–time graph of a particle moving along a straight line is a parabola with vertical axis, opening downward, with its vertex at t = 3 s, and the particle is at x = 0 at t = 0 and t = 6 s. Which statement is correct?","options":["The particle's speed is maximum at t = 3 s","The particle's acceleration is zero at t = 3 s","The particle's acceleration is constant and negative, and its velocity at t = 6 s is equal and opposite to that at t = 0","The average velocity over 0–6 s is equal to the velocity at t = 3 s, which is maximum"],"answer":2,"explanation":"A parabola x(t) means x is quadratic in t, so the acceleration is constant; opening downward means it is negative. The velocity (slope) is zero at the vertex t = 3 s, where the speed is minimum, not maximum. By symmetry the slopes at t = 0 and t = 6 s are equal in size and opposite in sign; the average velocity over 0–6 s is zero, which happens to equal v(3) = 0, but that is a minimum speed.","difficulty":"moderate","source":"JEE Main"},
];

export default questions;
